import { Router } from "express";
import { asyncHandler } from "../../../shared/http/async-handler.js";
import { ensureAuthenticated, ensurePermissions } from "../../auth/middlewares/auth.middleware.js";
import { AutorizacaoComprasController } from "../controllers/autorizacao-compras.controller.js";
const controller = new AutorizacaoComprasController();
export const autorizacaoComprasRoutes = Router();
const permissoesLeitura = ["ADMINISTRADOR", "OPERADOR", "LEITURA_APENAS"];
const permissoesEscrita = ["ADMINISTRADOR", "OPERADOR"];
const permissaoExclusao = ["ADMINISTRADOR"];
autorizacaoComprasRoutes.get("/", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.listar.bind(controller)));
autorizacaoComprasRoutes.post("/", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.criar.bind(controller)));
autorizacaoComprasRoutes.put("/:id", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.atualizar.bind(controller)));
autorizacaoComprasRoutes.delete("/:id", ensureAuthenticated, ensurePermissions(permissaoExclusao), asyncHandler(controller.excluir.bind(controller)));
autorizacaoComprasRoutes.get("/:id/cotacoes", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.listarCotacoes.bind(controller)));
autorizacaoComprasRoutes.post("/:id/cotacoes", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.criarCotacao.bind(controller)));
autorizacaoComprasRoutes.delete("/:id/cotacoes/:quoteId", ensureAuthenticated, ensurePermissions(permissaoExclusao), asyncHandler(controller.excluirCotacao.bind(controller)));
autorizacaoComprasRoutes.get("/fornecedores/cnpj/:cnpj", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.buscarFornecedorPorCnpj.bind(controller)));
autorizacaoComprasRoutes.post("/:id/reservas-bancarias", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.registrarReservaBancaria.bind(controller)));
autorizacaoComprasRoutes.get("/:id/reservas-bancarias", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.listarReservas.bind(controller)));
autorizacaoComprasRoutes.delete("/:id/reservas-bancarias/:contaId", ensureAuthenticated, ensurePermissions(permissaoExclusao), asyncHandler(controller.removerReservaBancaria.bind(controller)));
autorizacaoComprasRoutes.post("/:id/autorizacao-pagamento", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.gerarAutorizacaoPagamento.bind(controller)));
